   {[{icon:CalendarDays,title:'Plan a visit',desc:'Choose a service or tell us what you need.'},{icon:Activity,title:'Know what’s next',desc:'Follow your progress through each care step.'},{icon:HeartPulse,title:'One connected team',desc:'From reception to pharmacy, your care stays coordinated.'}].map(({icon:Icon,title,desc})=><div key={title} className="panel flex items-start gap-4 p-5"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#e8ece9] text-[#607469]"><Icon size={18}/></div><div><h3 className="text-sm font-semibold">{title}</h3><p className="mt-1 text-xs leading-relaxed text-[#7a847e]">{desc}</p></div></div>)}
